func (c *Core) aoOpenImpl(sp *AOStream, inHigh, inLow []float64, startIdx, optInFastPeriod, optInSlowPeriod int32, outBegIdx, outNBElement *int32, outReal []float64, outStride int32) RetCode {
	var sumFast float64
	var sumSlow float64
	var medianPrice float64
	var tempReal float64
	var i int32
	var outIdx int32
	var trailingFastIdx int32
	var trailingSlowIdx int32
	var lookbackTotal int32
	if len(inHigh) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inHigh))
	endIdx := historyLen - 1
	if len(inLow) != len(inHigh) {
		return BadParam
	}
	if optInFastPeriod == IntegerDefault {
		optInFastPeriod = 5
	} else if optInFastPeriod < 2 || optInFastPeriod > 100000 {
		return BadParam
	}
	if optInSlowPeriod == IntegerDefault {
		optInSlowPeriod = 34
	} else if optInSlowPeriod < 2 || optInSlowPeriod > 100000 {
		return BadParam
	}
	if startIdx >= historyLen {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	lookbackTotal = c.aoLookback(optInFastPeriod, optInSlowPeriod)
	if startIdx < lookbackTotal {
		startIdx = lookbackTotal
	}
	if startIdx > endIdx {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	sumFast = 0.0
	sumSlow = 0.0
	trailingFastIdx = startIdx - (optInFastPeriod - 1)
	trailingSlowIdx = startIdx - (optInSlowPeriod - 1)
	i = startIdx - lookbackTotal
	for i < startIdx {
		medianPrice = (inHigh[i] + inLow[i]) / 2.0
		if i >= trailingFastIdx {
			sumFast += medianPrice
		}
		if i >= trailingSlowIdx {
			sumSlow += medianPrice
		}
		i = i + 1
	}
	outIdx = 0
	for i <= endIdx {
		medianPrice = (inHigh[i] + inLow[i]) / 2.0
		sumFast += medianPrice
		sumSlow += medianPrice
		i = i + 1
		tempReal = sumFast/float64(optInFastPeriod) - sumSlow/float64(optInSlowPeriod)
		sumFast -= (inHigh[trailingFastIdx] + inLow[trailingFastIdx]) / 2.0
		sumSlow -= (inHigh[trailingSlowIdx] + inLow[trailingSlowIdx]) / 2.0
		trailingFastIdx = trailingFastIdx + 1
		trailingSlowIdx = trailingSlowIdx + 1
		outReal[outIdx*outStride] = tempReal
		outIdx = outIdx + 1
	}
	*outNBElement = outIdx
	*outBegIdx = startIdx
	cap_trailingFastIdx := i - trailingFastIdx
	if cap_trailingFastIdx < 1 || cap_trailingFastIdx > historyLen {
		return InternalError
	}
	capRing_trailingFastIdx_derived := make([]float64, max(cap_trailingFastIdx, 1))
	for fillJ := historyLen - cap_trailingFastIdx; fillJ < historyLen; fillJ++ {
		capRing_trailingFastIdx_derived[fillJ-(historyLen-cap_trailingFastIdx)] = (inHigh[fillJ] + inLow[fillJ]) / 2.0
	}
	cap_trailingSlowIdx := i - trailingSlowIdx
	if cap_trailingSlowIdx < 1 || cap_trailingSlowIdx > historyLen {
		return InternalError
	}
	capRing_trailingSlowIdx_derived := make([]float64, max(cap_trailingSlowIdx, 1))
	for fillJ := historyLen - cap_trailingSlowIdx; fillJ < historyLen; fillJ++ {
		capRing_trailingSlowIdx_derived[fillJ-(historyLen-cap_trailingSlowIdx)] = (inHigh[fillJ] + inLow[fillJ]) / 2.0
	}
	sp.optInFastPeriod = optInFastPeriod
	sp.optInSlowPeriod = optInSlowPeriod
	sp.sumFast = sumFast
	sp.sumSlow = sumSlow
	sp.ringPos_trailingFastIdx = 0
	sp.ringCap_trailingFastIdx = cap_trailingFastIdx
	sp.ring_trailingFastIdx_derived = capRing_trailingFastIdx_derived
	sp.ringPos_trailingSlowIdx = 0
	sp.ringCap_trailingSlowIdx = cap_trailingSlowIdx
	sp.ring_trailingSlowIdx_derived = capRing_trailingSlowIdx_derived
	sp.cur_outReal = outReal[(*outNBElement-1)*outStride]
	return Success
}

