// AOOpen opens a live [AOStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.AO] writes
// there.
//
// inHigh and inLow are the histories, of one length; the parameters are those
// of [Core.AO].
//
// The error is [InsufficientHistory] for a history of at most [Core.AOLookback]
// bars, [OutOfRangeEndIndex] for one longer than [IndexMax]+1 bars, and
// [BadParam] for a parameter out of range or histories of different lengths.
func (c *Core) AOOpen(inHigh, inLow []float64, optInFastPeriod, optInSlowPeriod int) (*AOStream, float64, error) {
	if !fitsInt32(optInFastPeriod) {
		return nil, 0, BadParam
	}
	if !fitsInt32(optInSlowPeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.aoOpenInternal(inHigh, inLow, 0, int32(optInFastPeriod), int32(optInSlowPeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// AOOpenAndFill opens a stream as [Core.AOOpen] does and also writes the
// outputs over the whole history, as [Core.AO] writes them for bars 0 through
// len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.AOLookback] values and share no
// memory with an input or another output.
//
// The errors are those of [Core.AOOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) AOOpenAndFill(inHigh, inLow []float64, optInFastPeriod, optInSlowPeriod int, outReal []float64) (*AOStream, OutRange, error) {
	if !fitsInt32(optInFastPeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInSlowPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.aoLookback(int32(optInFastPeriod), int32(optInSlowPeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.aoOpenAndFillInternal(inHigh, inLow, 0, int32(optInFastPeriod), int32(optInSlowPeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
